#include <optional>
#include <string>

std::optional<std::u16string> toUtf16(const std::string& utf8)
{
    std::u16string out;
    std::size_t i{ 0 };
    while (i < utf8.size())
    {
        const auto lead{ static_cast<unsigned char>(utf8[i]) };
        char32_t cp{ 0 };
        int extra{ 0 };
        if (lead < 0x80) { cp = lead; extra = 0; }
        else if ((lead & 0xE0) == 0xC0) { cp = lead & 0x1F; extra = 1; }
        else if ((lead & 0xF0) == 0xE0) { cp = lead & 0x0F; extra = 2; }
        else if ((lead & 0xF8) == 0xF0) { cp = lead & 0x07; extra = 3; }
        else return std::nullopt;                                 // a continuation byte or an invalid lead

        if (i + static_cast<std::size_t>(extra) >= utf8.size())
            return std::nullopt;                                  // cut short: not enough bytes left
        for (int k{ 1 }; k <= extra; ++k)
        {
            const auto next{ static_cast<unsigned char>(utf8[i + static_cast<std::size_t>(k)]) };
            if ((next & 0xC0) != 0x80) return std::nullopt;
            cp = (cp << 6) | (next & 0x3F);
        }
        i += static_cast<std::size_t>(extra) + 1;

        if (cp > 0x10FFFF) return std::nullopt;
        if (cp <= 0xFFFF)
        {
            out.push_back(static_cast<char16_t>(cp));
        }
        else
        {
            const char32_t v{ cp - 0x10000 };
            out.push_back(static_cast<char16_t>(0xD800 + (v >> 10)));
            out.push_back(static_cast<char16_t>(0xDC00 + (v & 0x3FF)));
        }
    }
    return out;
}

unitTests:
TEST("plain ASCII") { CHECK(*toUtf16("Rook") == std::u16string(u"Rook")); }
TEST("an empty string") { CHECK(toUtf16("")->empty()); }
TEST("two-byte characters") { CHECK(*toUtf16("Zo\xC3\xAB") == std::u16string(u"Zoë")); }
TEST("three-byte characters") { CHECK(*toUtf16("\xE6\x97\xA5\xE6\x9C\xAC") == std::u16string(u"日本")); }
TEST("a four-byte character becomes a surrogate pair")
{
    const std::u16string r{ *toUtf16("\xF0\x9F\x98\x80") };     // U+1F600
    CHECK_EQ(r.size(), std::size_t{ 2 });
    CHECK_EQ(static_cast<int>(r[0]), 0xD83D);
    CHECK_EQ(static_cast<int>(r[1]), 0xDE00);
}
TEST("mixed text") { CHECK_EQ(toUtf16("a\xC3\xA9\xE2\x82\xAC\xF0\x9F\x98\x80z")->size(), std::size_t{ 6 }); }
TEST("a stray continuation byte") { CHECK(!toUtf16("a\x80").has_value()); }
TEST("a sequence cut short") { CHECK(!toUtf16("Zo\xC3").has_value()); CHECK(!toUtf16("\xE6\x97").has_value()); }
TEST("a bad continuation byte") { CHECK(!toUtf16("\xC3\x41").has_value()); }
TEST("an impossible lead byte") { CHECK(!toUtf16("\xFF").has_value()); }

